const revenue = $('Fetch Historical Revenue').all().map(i => i.json);
const pipeline = $('Fetch Pipeline Data').all().map(i => i.json);

// Sort by date, take last 12 months
const sorted = revenue.sort((a,b) => new Date(a['Month']) - new Date(b['Month'])).slice(-12);
const values = sorted.map(r => parseFloat(r['Revenue'] || 0));

// Simple linear regression
const n = values.length;
const x = values.map((_,i) => i);
const sumX = x.reduce((a,b)=>a+b,0);
const sumY = values.reduce((a,b)=>a+b,0);
const sumXY = x.reduce((a,xi,i)=>a+xi*values[i],0);
const sumX2 = x.reduce((a,xi)=>a+xi*xi,0);
const slope = (n*sumXY - sumX*sumY) / (n*sumX2 - sumX*sumX);
const intercept = (sumY - slope*sumX) / n;

const forecast3m = [1,2,3].map(i => Math.max(0, Math.round(slope*(n+i-1) + intercept)));

const mom_growth = values.length >= 2 ? (((values[values.length-1] - values[values.length-2]) / values[values.length-2]) * 100).toFixed(1) : 0;
const avg_3m = values.slice(-3).reduce((a,b)=>a+b,0) / 3;

// Pipeline weighted
const weightedPipeline = pipeline.reduce((s,d) => s + parseFloat(d['Deal Value']||0) * (parseFloat(d['Probability %']||0)/100), 0);

return [{ json: { historical: sorted, values, forecast_3m: forecast3m, slope: slope.toFixed(0), mom_growth, avg_3m: avg_3m.toFixed(0), weighted_pipeline: weightedPipeline.toFixed(0), last_month: values[values.length-1] || 0 } }];

const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const forecast = JSON.parse(raw);
return [{ json: { ...forecast, metrics: $('Calculate Trends').item.json } }];

